<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/functions.php';
require_login();
$orgId = current_org();
$stmt = db()->prepare('SELECT id, member_code, full_name, position, issue_date, status, card_token FROM members WHERE org_id = :org_id ORDER BY created_at DESC, id DESC LIMIT 100');
$stmt->execute(['org_id' => $orgId]);
$members = $stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard · ID Generator</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><nav class="navbar navbar-expand bg-dark navbar-dark"><div class="container"><a class="navbar-brand" href="/dashboard.php">ID Generator</a><form method="post" action="/logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn btn-outline-light btn-sm" type="submit">Sign out</button></form></div></nav><main class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><h1 class="h3 mb-0">Members</h1><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="/import.php">Bulk Import (CSV)</a><a class="btn btn-primary" href="/api/generate_batch.php">Generate All Cards</a></div></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Code</th><th>Name</th><th>Position</th><th>Issue date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($members as $member): ?><tr><td><?= e((string) $member['member_code']) ?></td><td><?= e((string) $member['full_name']) ?></td><td><?= e((string) ($member['position'] ?: '-')) ?></td><td><?= e((string) ($member['issue_date'] ?: '-')) ?></td><td><span class="badge <?= $member['status'] === 'active' ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= e(ucfirst((string) $member['status'])) ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="/api/generate_single.php?id=<?= (int) $member['id'] ?>">PDF</a> <a class="btn btn-sm btn-outline-secondary" target="_blank" rel="noopener" href="/api/verify.php?token=<?= e((string) $member['card_token']) ?>">Verify</a></td></tr><?php endforeach; ?><?php if (!$members): ?><tr><td colspan="6" class="text-center text-muted py-4">No members yet. Import a CSV to get started.</td></tr><?php endif; ?></tbody></table></div></main></body></html>
